    # boundary rows into the background tail with color 1.
    from collections import Counter, deque
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy in (-1, 0, 1):
                    for dx in (-1, 0, 1):
                        yy, xx = y + dy, x + dx
                        if (dy or dx) and 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and (yy, xx) not in seen:
                            seen.add((yy, xx)); q.append((yy, xx))
            edge = max(x for y, x in comp)
            for y in {y for y, x in comp if x == edge}:
                for x in range(edge + 1, w):
                    out[y][x] = 1
    return out

